export function referenceSection(id: string): string {
  if (id === "all") {
    return REFERENCE_SECTIONS.map((s) => s.body).join("\n\n---\n\n");
  }
  return REFERENCE_SECTIONS.find((s) => s.id === id)?.body ?? "";
}
